Action.Str:
// Tasker JavaScriptlet: HTTP Request supplies http_data and http_response_code.
var haze_title = "Singapore haze - PSI unavailable";
var haze_text = "Could not retrieve the latest PSI. Check your connection or haze.gov.sg.";
try {
    if (String(typeof http_response_code === "undefined" ? "" : http_response_code) !== "200") {
        throw new Error("HTTP request failed");
    }
    var payload = JSON.parse(String(http_data));
    if (payload.code !== 0 || !payload.data || !Array.isArray(payload.data.items)) {
        throw new Error("Invalid API response");
    }
    var latest = null;
    var latestTime = -Infinity;
    payload.data.items.forEach(function (item) {
        var time = Date.parse(item.timestamp);
        if (isFinite(time) && time > latestTime) {
            latest = item;
            latestTime = time;
        }
    });
    if (!latest) throw new Error("No timestamped readings");
    var age = Date.now() - latestTime;
    if (age < -300000) throw new Error("Future reading");
    var regions = ["north", "south", "east", "west", "central"];
    var readings = latest.readings.psi_twenty_four_hourly;
    var values = regions.map(function (region) {
        var value = readings[region];
        if (typeof value !== "number" || !isFinite(value) || value < 0 || Math.floor(value) !== value) {
            throw new Error("Missing or invalid regional PSI");
        }
        return value;
    });
    var low = Math.min.apply(null, values);
    var high = Math.max.apply(null, values);
    var category = high <= 50 ? "Good" : high <= 100 ? "Moderate" :
        high <= 200 ? "Unhealthy" : high <= 300 ? "Very Unhealthy" : "Hazardous";
    var advice = high <= 100 ? "Normal activities." : high <= 200 ?
        "Reduce prolonged or strenuous outdoor exertion." : high <= 300 ?
        "Avoid prolonged or strenuous outdoor exertion." : "Minimise outdoor activity.";
    var sensitive = high <= 100 ? "" : high <= 200 ?
        "Elderly, pregnant women and children: minimise prolonged or strenuous outdoor exertion. Heart/lung conditions: avoid it." :
        high <= 300 ? "Elderly, pregnant women and children: minimise outdoor activity. Heart/lung conditions: avoid outdoor activity." :
        "Elderly, pregnant women, children and people with heart/lung conditions: avoid outdoor activity.";
    var range = low === high ? String(high) : low + "-" + high;
    var worst = regions.filter(function (region, index) { return values[index] === high; }).join(", ");
    // UTC+8 formatting is independent of the phone's display time zone.
    var readingTime = new Date(latestTime + 8 * 3600000).toISOString().slice(0, 16).replace("T", " ") + " SGT";
    if (age > 2 * 3600000) {
        haze_title = "Singapore haze - stale PSI data";
        haze_text = "Latest reading is over 2 hours old (" + readingTime + "). Last 24-hour PSI: " + range +
            ". Current health category unavailable. Check haze.gov.sg.";
    } else {
        haze_title = "Singapore haze - PSI " + range + " (" + category + ")";
        haze_text = "24-hour PSI, highest " + high + " in " + worst + ": " + category + ".\n" + advice +
            (sensitive ? "\n" + sensitive : "") + "\nReading: " + readingTime + " | NEA/data.gov.sg";
    }
} catch (error) {
    // Keep the failure notification; never infer a healthy PSI from missing data.
}
